def inspect_call_family(node)
  return { family: :call, empty: true } unless node
  receiver = node.receiver
  selector = node.method_name
  args = node.arguments
  parenthesized = node.parenthesized?
  operator = node.operator_method?
  setter = node.setter_method?
  unary = node.unary_operation?
  prefix_not = node.prefix_not?
  dot = node.dot?
  safe_nav = node.csend_type?
  chained = %i[send csend].include?(node.parent&.type)
  block_parent = %i[block numblock].include?(node.parent&.type)
  {
    family: :call, type: node.type, selector: selector, arity: args.size,
    parenthesized: parenthesized, operator: operator, setter: setter, unary: unary,
    prefix_not: prefix_not, dot: dot, safe_nav: safe_nav, chained: chained,
    block_parent: block_parent, receiver: receiver&.type, source: node.source
  }
end


def inspect_block_family(node)
  return { family: :block, empty: true } unless node
  send_node = node.send_node
  braces = node.braces?
  keywords = node.keywords?
  lambda_like = send_node&.lambda?
  numblock = node.numblock_type?
  args = node.arguments
  body = node.body
  {
    family: :block, type: node.type, braces: braces, keywords: keywords,
    lambda_like: lambda_like, numblock: numblock, send: send_node&.type,
    selector: send_node&.method_name,
    arg_count: args&.size, body: body&.type,
    multiline: node.multiline?, source: node.source
  }
end


