def profile_block_argument(first_arg)
  return { block_like: false, empty: true } unless first_arg
  block_like = %i[block numblock].include?(first_arg.type)
  send_node = first_arg.send_node if first_arg.respond_to?(:send_node)
  braces = first_arg.braces? if first_arg.respond_to?(:braces?)
  keywords = first_arg.keywords? if first_arg.respond_to?(:keywords?)
  lambda_like = send_node.lambda? if send_node.respond_to?(:lambda?)
  {
    block_like: block_like, braces: braces, keywords: keywords, numblock: first_arg.numblock_type?,
    lambda_like: lambda_like, send: send_node&.type, inspect: inspect_expression_node(first_arg)
  }
end

