def character_before_begin(node)
  return nil unless node&.loc.respond_to?(:begin) && node.loc.begin
  pos = node.loc.begin.begin_pos
  return nil if pos.zero?
  node.source_range.source_buffer.source[pos - 1]
end

def character_after_end(node)
  return nil unless node&.loc.respond_to?(:end) && node.loc.end
  pos = node.loc.end.end_pos
  source = node.source_range.source_buffer.source
  pos < source.length ? source[pos] : nil
end

