def expression_precedence_weight(node)
  return 0 unless node
  type = node.type
  return 19 if %i[and or].include?(type) && node.semantic_operator?
  table = { and: 11, or: 12, irange: 13, erange: 13 }
  return 14 if type == :if && node.ternary?
  table[type] || precedence_weight_for_send_operator(node)
end


def precedence_weight_for_send_operator(node)
  return 0 unless node
  return 0 unless node.respond_to?(:method_name)
  name = node.method_name.to_s
  table = {
    "**" => 2, "+@" => 3, "-@" => 3, "!" => 3, "~" => 3,
    "*" => 4, "/" => 4, "%" => 4, "+" => 5, "-" => 5
  }
  table[name] || precedence_weight_for_send_operator_rest(name)
end


def precedence_weight_for_send_operator_rest(name)
  table = {
    "<<" => 6, ">>" => 6, "&" => 7, "|" => 8, "^" => 8,
    ">" => 9, ">=" => 9, "<" => 9, "<=" => 9,
    "<=>" => 10, "==" => 10, "===" => 10, "!=" => 10, "=~" => 10, "!~" => 10
  }
  table[name] || 0
end


